Ext.define('BNK.view.Budget.exp.ExpNteApr03MViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.budget.exp.expnteapr03m',

    config: {
        viewId: 'ExpNteApr03M'
    },

    /* 조회일자 변경시 해당연도에 존재하는 결재 문서 리스트 가져오기 */
    onSearchYearChange: function(field, newValue, oldValue, eOpts) {

        if(newValue.toString().length == 4){
            var me = this,
                vm = me.getViewModel(),
                refs = me.getReferences(),
                command = vm.get('command'),
                vwId = refs.vwId,
                searchVwIdStore = vwId.getStore();
            data = {
                command : command,
                searchYear : newValue
            };

            if(command == Constants.sanction.DEPT_COMPLETED_BOX){ // 부서완료함인 경우 부서구분 포함
                data.dpDvcdNm = '부서';
            }

            // 조회문서 데이터 초기화
            searchVwIdStore.removeAll();

            Ext.Ajax.request({
                headers : {
                    serviceId : 'COMAPR0001R03M'
                },
                jsonData:data,
                success : function(response, scope) {
                    // 결재 조회 조건을 리스트에 있는 것들만으로 전달
                    var res = JSON.parse(response.responseText);
                    var edocCodeList = res.edocCodeList;

                    for (var i in edocCodeList) {
                        var record = {
                            text : edocCodeList[i].edocNm,
                            value : edocCodeList[i].edocCd
                        };
                        searchVwIdStore.add(record);
                    }
                },
                failure : function(response){
                    Ext.Msg.alert('오류', '조회문서를 가져오는 도중 오류가 발생했습니다.');
                }
            });
        }

    },

    /* 닫기 */
    onBtnCloseTap: function(button, e, eOpts) {
        this.getView().close();
    },

    /* 조회 */
    onBtnSearchTap: function(button, e, eOpts) {
        var me = this,
            view = me.getView(),
            refs = me.getReferences(),
            values = refs.form.getValues();

        view.fireEvent('search', values, view);
    },

    /* 초기화 */
    initialize: function(component, eOpts) {
        var me = this,
            refs = me.getReferences(),
            vm = me.getViewModel(),
            searchYear = refs.searchYear,
            vwId = refs.vwId,
            searchVwIdStore = component.initialConfig.searchVwIdStore, // 검색조건 : 결재문서명
            command = component.command;

        vm.set('command', command);

        searchYear.setValue(component.initialConfig.searchYear);
        vwId.setStore(searchVwIdStore);

    }

});